'use strict';
(() => {
 const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const data=window.ENGLISH_DATA||[], byId=new Map(data.map(w=>[w.id,w]));
 const KEY='word-garden-v1';let saved={favorites:[],learned:[],speed:1,last:'letter_a-apple'};
 try{const p=JSON.parse(localStorage.getItem(KEY));if(p&&typeof p==='object')saved={...saved,...p};}catch{}
 const validSet=a=>new Set((Array.isArray(a)?a:[]).filter(x=>byId.has(x)));
 const favorites=validSet(saved.favorites),learned=validSet(saved.learned);let speed=[.5,.75,1,1.25,1.5].includes(Number(saved.speed))?Number(saved.speed):1;
 let active=byId.has(saved.last)?saved.last:data[0]?.id,letter='all',filter='all',query='',page=0,filtered=[],quiz=null,toastTimer,seq=0,storageWarned=false;
 const pageSize=12,audio=new Audio();audio.preload='none';
 function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3600);}
 function persist(){try{localStorage.setItem(KEY,JSON.stringify({favorites:[...favorites],learned:[...learned],speed,last:active}));}catch{if(!storageWarned){toast('瀏覽器無法儲存紀錄，本次仍可正常練習。');storageWarned=true;}}}
 function stop(){seq++;audio.pause();audio.removeAttribute('src');audio.load();$('playerBar').hidden=true;}
 async function play(url,label){stop();if(!url){toast('原教材未提供可用的對應音檔。');return;}
  const token=seq;audio.src=url;audio.playbackRate=speed;audio.preservesPitch=true;$('playerBar').hidden=false;$('playingLabel').textContent=label;$('playState').textContent='正在載入原教材音檔…';$('playRate').textContent=speed+'×';$('audioProgress').value=0;
  try{await audio.play();if(token===seq)$('playState').textContent='播放中 · 聽完後，換你說說看';}catch(e){if(token!==seq)return;stop();toast(e.name==='NotAllowedError'?'請再按一次播放，允許瀏覽器播放聲音。':'音檔無法播放，請確認檔案或網路後再試一次。');}
 }
 audio.addEventListener('timeupdate',()=>{$('audioProgress').value=Number.isFinite(audio.duration)&&audio.duration?audio.currentTime/audio.duration:0;});
 audio.addEventListener('ended',()=>{$('playState').textContent='播放完畢 · 換你跟著唸一次';$('audioProgress').value=1;});
 audio.addEventListener('error',()=>{if(audio.getAttribute('src')){$('playState').textContent='音檔載入失敗，請重新點選播放。';toast('音檔載入失敗，請確認檔案或網路。');}});
 $('stopAudio').onclick=stop;
 function renderAlphabet(){const counts=window.DATA_AUDIT?.letterCounts||{};$('alphabet').innerHTML=['all',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(l=>`<button data-letter="${l}" class="${letter===l?'active':''}" aria-pressed="${letter===l}" title="${l==='all'?'全部單字':`${l}：${counts[l]||0} 筆`}">${l==='all'?'全部':l}</button>`).join('');}
 function updateFiltered(){filtered=data.filter(w=>(letter==='all'||w.letter===letter)&&(filter!=='saved'||favorites.has(w.id))&&(filter!=='learned'||learned.has(w.id))&&(!query||[w.word,w.meaning,...w.examples.flatMap(e=>[e.english,e.translation])].join(' ').toLocaleLowerCase().includes(query)));if(!filtered.some(w=>w.id===active)){active=filtered[0]?.id;stop();}page=Math.min(page,Math.max(0,Math.ceil(filtered.length/pageSize)-1));renderList();renderDetail();}
 function renderList(){const items=filtered.slice(page*pageSize,(page+1)*pageSize);$('resultCount').textContent=filtered.length+' 筆';$('listTitle').textContent=letter==='all'?(filter==='saved'?'我的收藏':filter==='learned'?'已學會':'全部單字'):letter+' 開頭的單字';$('pageLabel').textContent=filtered.length?`${page+1} / ${Math.ceil(filtered.length/pageSize)} 頁`:'0 / 0 頁';$('prevPage').disabled=page===0;$('nextPage').disabled=(page+1)*pageSize>=filtered.length;
  $('wordList').innerHTML=items.length?items.map(w=>`<button class="word-item ${active===w.id?'active':''}" data-id="${esc(w.id)}" aria-pressed="${active===w.id}"><span><b>${esc(w.word)}</b><small>${esc(w.meaning)}</small></span><span aria-hidden="true">${learned.has(w.id)?'✓':favorites.has(w.id)?'★':'↗'}</span></button>`).join(''):`<div class="empty">${letter==='X'?'原教材沒有 X 開頭的單字。':filter==='saved'?'還沒有符合條件的收藏。<br>在單字旁按「收藏」，留下想練習的單字。':filter==='learned'?'目前沒有符合條件的已學會單字。':'找不到符合條件的單字。<br>試試其他關鍵字或字母。'}</div>`;
  $('learnedCount').textContent=learned.size;
 }
 function renderDetail(){const w=byId.get(active);if(!w){$('wordDetail').innerHTML='<div class="empty"><span class="sprout">✳</span><h2>換個方向，繼續探索。</h2><p>選擇其他字母、切換「全部單字」，<br>或清除搜尋條件。</p><button class="outline" id="resetFilters">顯示全部單字</button></div>';$('resetFilters').onclick=resetFilters;return;}
  const idx=filtered.findIndex(x=>x.id===active);$('wordDetail').innerHTML=`<div class="detail-top"><span class="tag">LETTER ${w.letter} <span aria-hidden="true">/</span> 單字學習</span><button class="bookmark" id="favorite" aria-pressed="${favorites.has(w.id)}">${favorites.has(w.id)?'★ 已收藏':'☆ 收藏單字'}</button></div><h3 class="word-title" lang="en">${esc(w.word)}</h3><div class="phonetics">${w.phonetics.filter(p=>p.url).map(p=>`<img src="${p.url}" alt="${esc(w.word)} 的原教材音標" loading="lazy">`).join('')}</div><p class="meaning">${esc(w.meaning||'原教材未提供中文解釋')}</p><div class="audio-controls"><button class="primary" id="playWord" ${!w.audio?'disabled':''}><span aria-hidden="true">◖ ))</span> 聽單字發音</button><label class="speed-label">播放速度 <select id="speed" aria-label="播放速度">${[.5,.75,1,1.25,1.5].map(n=>`<option value="${n}" ${speed===n?'selected':''}>${n}×${n===1?' 標準':''}</option>`).join('')}</select></label></div><div class="examples"><div class="example-title"><b>放進句子裡，一起學。</b><span>EXAMPLE ${String(w.examples.length).padStart(2,'0')}</span></div>${w.examples.map((e,i)=>`<div class="example"><p class="example-english" lang="en">${esc(e.english)}</p><p class="example-translation">${esc(e.translation||'原教材未提供中文翻譯')}</p>${e.audio.map((a,j)=>`<button data-example="${i}" data-track="${j}" ${!a?'disabled':''}>▷ ${e.audio.length>1?'播放片段 '+(j+1):'聽例句發音'}</button>`).join(' ')}${e.warning?`<p class="warning">${esc(e.warning)}</p>`:''}</div>`).join('')||'<p class="muted">原教材未提供例句。</p>'}</div><div class="detail-bottom"><button id="markLearned" class="learned-btn" aria-pressed="${learned.has(w.id)}">${learned.has(w.id)?'✓ 已學會':'✓ 這個單字，我學會了'}</button><div class="detail-nav"><button id="prevWord" ${idx<=0?'disabled':''}>← 上一個</button><button id="nextWord" ${idx<0||idx>=filtered.length-1?'disabled':''}>下一個 →</button></div></div>`;
  $('playWord').onclick=()=>play(w.audio,w.word);$('speed').onchange=e=>{speed=Number(e.target.value);audio.playbackRate=speed;$('playRate').textContent=speed+'×';persist();};
  $('favorite').onclick=()=>{favorites.has(w.id)?favorites.delete(w.id):favorites.add(w.id);persist();updateFiltered();};$('markLearned').onclick=()=>{learned.has(w.id)?learned.delete(w.id):learned.add(w.id);persist();updateFiltered();};
  $('prevWord').onclick=()=>selectWord(filtered[idx-1]?.id);$('nextWord').onclick=()=>selectWord(filtered[idx+1]?.id);
  $('wordDetail').querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>play(w.examples[+b.dataset.example].audio[+b.dataset.track],w.word+' · 例句 '+(+b.dataset.example+1)));
 }
 function selectWord(id){if(!byId.has(id))return;stop();active=id;const idx=filtered.findIndex(w=>w.id===id);if(idx>=0)page=Math.floor(idx/pageSize);persist();renderList();renderDetail();}
 function resetFilters(){filter='all';letter='all';query='';page=0;$('search').value='';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter==='all');b.setAttribute('aria-pressed',b.dataset.filter==='all');});renderAlphabet();updateFiltered();}
 $('alphabet').onclick=e=>{const b=e.target.closest('[data-letter]');if(!b)return;letter=b.dataset.letter;page=0;renderAlphabet();updateFiltered();};
 $('wordList').onclick=e=>{const b=e.target.closest('[data-id]');if(b)selectWord(b.dataset.id);};
 $('search').addEventListener('input',e=>{query=e.target.value.trim().toLocaleLowerCase();page=0;updateFiltered();});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=0;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});updateFiltered();});
 $('prevPage').onclick=()=>{if(page>0){page--;renderList();$('wordList').scrollTop=0;$('wordList').scrollLeft=0;}};$('nextPage').onclick=()=>{if((page+1)*pageSize<filtered.length){page++;renderList();$('wordList').scrollTop=0;$('wordList').scrollLeft=0;}};
 $('teacher').onclick=()=>{const on=document.body.classList.toggle('projector');$('teacher').setAttribute('aria-pressed',on);$('teacher').innerHTML=on?'▣ 離開投影':'▣ 教師投影';};
 function showLearn(scroll=true){stop();$('study').hidden=false;$('quizSection').hidden=true;$('learnNav').classList.add('active');$('quizNav').classList.remove('active');if(scroll)$('study').scrollIntoView({block:'start'});}
 function showQuiz(){stop();$('study').hidden=true;$('quizSection').hidden=false;$('quizNav').classList.add('active');$('learnNav').classList.remove('active');quiz=null;quizSetup();$('quizSection').scrollIntoView({block:'start'});}
 const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
 function quizSetup(){$('quizBody').innerHTML=`<span class="tag">選擇今天的練習</span><h3>聽一聽，也想一想。</h3><p class="quiz-intro">每次最多 10 題，題目來自原教材。答題後會立即顯示答案，最後可以複習答錯的單字。</p><label>練習方式<select id="quizMode"><option value="listen">聽音選單字</option><option value="meaning">看英文選中文</option></select></label><label>出題範圍<select id="quizScope"><option value="current">目前篩選結果（${filtered.length} 筆）</option><option value="all">全部單字（${data.length} 筆）</option><option value="saved">我的收藏（${favorites.size} 筆）</option><option value="learned">已學會（${learned.size} 筆）</option></select></label><p class="quiz-intro">需有至少 4 個不同的可用選項。聽力使用原教材音檔；這是單字練習，不是口說發音評分。</p><button class="primary" id="startQuiz">開始練習 →</button>`;$('startQuiz').onclick=startQuiz;}
 function startQuiz(){const mode=$('quizMode').value,scope=$('quizScope').value;let pool=(scope==='current'?filtered:scope==='saved'?data.filter(w=>favorites.has(w.id)):scope==='learned'?data.filter(w=>learned.has(w.id)):data).filter(w=>mode==='listen'?w.audio:w.meaning);const text=w=>mode==='listen'?w.word:w.meaning;pool=pool.filter((w,i,a)=>a.findIndex(x=>text(x)===text(w))===i);if(pool.length<4){toast('這個範圍少於 4 個不同的可用選項，請改選全部單字或增加收藏。');return;}quiz={mode,pool,questions:shuffle(pool).slice(0,10),i:0,answers:[],options:[],answered:false};renderQuestion();}
 function renderQuestion(){stop();const q=quiz.questions[quiz.i];quiz.answered=false;const label=w=>quiz.mode==='listen'?w.word:w.meaning;quiz.options=shuffle([q,...shuffle(quiz.pool.filter(w=>w.id!==q.id&&label(w)!==label(q))).slice(0,3)]);$('quizBody').innerHTML=`<div class="quiz-meta"><span>${quiz.mode==='listen'?'聽音選單字':'看英文選中文'}</span><span>第 ${quiz.i+1} / ${quiz.questions.length} 題</span></div><p class="quiz-intro">${quiz.mode==='listen'?'按下播放，選出你聽到的單字。':'這個英文單字，在原教材中的中文解釋是？'}</p>${quiz.mode==='listen'?'<button id="quizListen" class="quiz-listen" aria-label="播放題目音檔">▷</button>':`<div class="quiz-prompt" lang="en">${esc(q.word)}</div>`}<div class="quiz-options">${quiz.options.map((w,i)=>`<button data-answer="${i}">${esc(label(w))}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback" role="status"></div><div class="quiz-actions"><button class="outline" id="restartQuiz">重新選擇範圍</button><button id="nextQuestion" class="primary" hidden>${quiz.i===quiz.questions.length-1?'查看練習結果':'下一題 →'}</button></div>`;
  if($('quizListen'))$('quizListen').onclick=()=>play(q.audio,'聽力練習 · 第 '+(quiz.i+1)+' 題');$('restartQuiz').onclick=()=>{stop();quiz=null;quizSetup();};$('quizBody').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));$('nextQuestion').onclick=()=>{quiz.i++;quiz.i<quiz.questions.length?renderQuestion():quizResult();};
 }
 function answer(index){if(!quiz||quiz.answered)return;quiz.answered=true;const q=quiz.questions[quiz.i],chosen=quiz.options[index],correct=chosen.id===q.id;quiz.answers.push({id:q.id,chosen:chosen.id,correct});$('quizBody').querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;const w=quiz.options[+b.dataset.answer];if(w.id===q.id)b.classList.add('correct');else if(w.id===chosen.id)b.classList.add('wrong');});$('quizFeedback').textContent=(correct?'答對了！':'再記住一次：')+' '+q.word+' — '+q.meaning;$('nextQuestion').hidden=false;}
 function quizResult(){stop();const right=quiz.answers.filter(a=>a.correct).length,wrong=quiz.answers.filter(a=>!a.correct);$('quizBody').innerHTML=`<span class="tag">PRACTICE COMPLETE</span><h3>每一次練習，都在進步。</h3><div class="score">${right}<span style="font-size:28px"> / ${quiz.questions.length}</span></div><p class="quiz-intro">${wrong.length?'再聽聽這些單字，下一次會更熟悉。':'全部答對了！試試新的字母或例句吧。'}</p>${wrong.map(a=>{const w=byId.get(a.id);return `<div class="review-row"><button data-review="${esc(w.id)}">▷ ${esc(w.word)}</button> — ${esc(w.meaning)}</div>`;}).join('')}<div class="quiz-actions" style="margin-top:28px"><button class="outline" id="resultLearn">返回單字學習</button><button class="primary" id="tryAgain">再練習一次 →</button></div>`;$('resultLearn').onclick=()=>showLearn();$('tryAgain').onclick=()=>{quiz=null;quizSetup();};$('quizBody').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const w=byId.get(b.dataset.review);play(w.audio,w.word);});}
 $('learnNav').onclick=()=>showLearn();$('backLearn').onclick=()=>showLearn();$('quizNav').onclick=showQuiz;
 function showInfo(){const a=window.DATA_AUDIT;$('infoContent').innerHTML=`<p>以 <b>English1200-0514.rar</b> 原教材重製，收錄 <b>${a.words.toLocaleString()} 筆單字／片語</b>與 <b>${a.examples.toLocaleString()} 組例句</b>。雖然原教材名稱為「1200」，實際獨立單字頁面為 ${a.words} 筆，沒有 X 開頭的單字頁面。</p><ul><li>保留原有英文、中文、例句及音標圖片；原教材的用字、拼字與詞性標記未自行修改。</li><li>發音直接使用原教材 MP3，播放速度可調整，沒有使用合成語音替代。</li><li>修正 18 處檔名大小寫對應；cheap 的例句原連結指向 cake.mp3，已標示待核對並停用該例句播放。</li><li>收藏與已學會紀錄只存放在目前瀏覽器，不會跨裝置同步。</li><li>教師投影模式可放大單字與例句；測驗包含聽音選字及英翻中選擇題。</li></ul><p><a href="audit.json" download>下載完整資料檢查紀錄 JSON</a> · <a href="asset-map.json" download>下載原始素材對照表</a></p><p class="muted">所有原始檔案完整保留於可下載專案中的 dist/original/。音檔已檢查路徑與檔案完整性，未逐段人工聽辨錄音內容。</p>`;$('infoDialog').showModal();}
 $('infoNav').onclick=showInfo;$('footerInfo').onclick=showInfo;$('closeInfo').onclick=()=>$('infoDialog').close();$('infoDialog').addEventListener('click',e=>{if(e.target===$('infoDialog')){const r=$('infoDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('infoDialog').close();}});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('infoDialog').open&&!$('study').hidden){e.preventDefault();$('search').focus();}});
 $('wordTotal').textContent=data.length.toLocaleString();renderAlphabet();updateFiltered();const initialIndex=filtered.findIndex(w=>w.id===active);if(initialIndex>=0){page=Math.floor(initialIndex/pageSize);renderList();}
})();
